def execute(arguments):
    """
    生成随机数据

    参数:
        arguments (dict): 包含以下字段
            - type (str): 生成类型，"number"（随机数，默认）、"float"（随机浮点数）、"string"（随机字符串）、"secure_string"（安全随机字符串）、"uuid"（UUID）、"password"（密码）
            - min (int): 最小值，number/float类型时使用，默认 0
            - max (int): 最大值，number/float类型时使用，默认 100
            - length (int): 字符串长度，string/secure_string/password类型时使用，默认 16
            - count (int): 生成数量，默认 1
            - charset (str): 字符集类型，string/secure_string类型时使用
                - "alphanumeric": 字母数字（默认）
                - "letters": 仅字母
                - "digits": 仅数字
                - "hex": 十六进制
                - "password": 包含特殊字符

    返回:
        dict: 包含生成结果的字典
            - success (bool): 是否成功
            - results (list): 生成的结果列表
            - count (int): 生成数量
            - error (str): 错误信息（失败时）
    """
    import random
    import string
    import uuid as uuid_module
    import secrets

    generator_type = arguments.get("type", "number")
    min_val = arguments.get("min", 0)
    max_val = arguments.get("max", 100)
    length = arguments.get("length", 16)
    count = arguments.get("count", 1)
    charset = arguments.get("charset", "alphanumeric")

    try:
        results = []

        for _ in range(count):
            if generator_type == "number":
                result = random.randint(min_val, max_val)

            elif generator_type == "float":
                result = random.uniform(min_val, max_val)

            elif generator_type == "string":
                if charset == "alphanumeric":
                    chars = string.ascii_letters + string.digits
                elif charset == "letters":
                    chars = string.ascii_letters
                elif charset == "digits":
                    chars = string.digits
                elif charset == "hex":
                    chars = string.hexdigits.lower()
                elif charset == "password":
                    chars = string.ascii_letters + string.digits + "!@#$%^&*()_+-=[]{}|;:,.<>?"
                else:
                    chars = charset
                result = ''.join(random.choice(chars) for _ in range(length))

            elif generator_type == "secure_string":
                if charset == "alphanumeric":
                    chars = string.ascii_letters + string.digits
                elif charset == "hex":
                    chars = string.hexdigits.lower()
                else:
                    chars = string.ascii_letters + string.digits
                result = ''.join(secrets.choice(chars) for _ in range(length))

            elif generator_type == "uuid":
                result = str(uuid_module.uuid4())

            elif generator_type == "password":
                chars = string.ascii_letters + string.digits + "!@#$%^&*"
                result = ''.join(secrets.choice(chars) for _ in range(length))

            else:
                return {"success": False, "error": f"未知的生成类型: {generator_type}"}

            results.append(result)

        return {
            "success": True,
            "results": results if count > 1 else results[0],
            "count": len(results)
        }
    except Exception as e:
        return {"success": False, "error": f"生成失败: {str(e)}"}
